/* Utility override for hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border-color: #334155;
  --focus-ring: #38bdf8;
  --error-color: #f87171;
  --error-bg: rgba(239, 68, 68, 0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.converter-container {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 32px 24px;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
}

.converter-header {
  text-align: center;
  margin-bottom: 24px;
}

.converter-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 6px;
}

.converter-header p {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.swatch-card {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.color-swatch {
  width: 100%;
  height: 110px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background-color: #000000;
  transition: background-color 0.15s ease, opacity 0.15s ease;
}

.color-swatch.invalid {
  background-color: #334155 !important;
  opacity: 0.5;
}

.hex-display-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.hex-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.hex-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-main);
}

.hex-value.invalid {
  color: var(--error-color);
}

.rgb-form {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input-group input {
  width: 100%;
  background-color: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  color: var(--text-main);
  font-size: 1rem;
  font-family: inherit;
  text-align: center;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.input-group input:hover {
  border-color: #475569;
}

.input-group input:focus-visible {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.input-group input:active {
  transform: scale(0.99);
}

.input-group input.has-error {
  border-color: var(--error-color);
  box-shadow: 0 0 0 2px rgba(248, 113, 113, 0.2);
}

.error-message {
  background-color: var(--error-bg);
  border: 1px solid var(--error-color);
  color: var(--error-color);
  font-size: 0.9rem;
  font-weight: 600;
  text-align: center;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
}

@media (max-width: 400px) {
  .converter-container {
    padding: 24px 16px;
  }

  .rgb-form {
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .input-group {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .input-group input {
    width: 100px;
    text-align: right;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const redInput = document.getElementById('red-input');
  const greenInput = document.getElementById('green-input');
  const blueInput = document.getElementById('blue-input');
  const hexOutput = document.getElementById('hex-output');
  const colorSwatch = document.getElementById('color-swatch');
  const errorMessage = document.getElementById('error-message');

  const inputs = [redInput, greenInput, blueInput];

  function isValidChannel(valStr) {
    if (valStr.trim() === '') {
      return false;
    }
    const num = Number(valStr);
    return !Number.isNaN(num) && Number.isInteger(num) && num >= 0 && num <= 255;
  }

  function componentToHex(c) {
    const hex = c.toString(16).toUpperCase();
    return hex.length === 1 ? '0' + hex : hex;
  }

  function updateConverter() {
    const rVal = redInput.value;
    const gVal = greenInput.value;
    const bVal = blueInput.value;

    const isRValid = isValidChannel(rVal);
    const isGValid = isValidChannel(gVal);
    const isBValid = isValidChannel(bVal);

    redInput.classList.toggle('has-error', !isRValid);
    greenInput.classList.toggle('has-error', !isGValid);
    blueInput.classList.toggle('has-error', !isBValid);

    if (isRValid && isGValid && isBValid) {
      const r = Number(rVal);
      const g = Number(gVal);
      const b = Number(bVal);
      const hex = `#${componentToHex(r)}${componentToHex(g)}${componentToHex(b)}`;

      hexOutput.textContent = hex;
      hexOutput.classList.remove('invalid');
      colorSwatch.style.backgroundColor = hex;
      colorSwatch.classList.remove('invalid');
      colorSwatch.setAttribute('aria-label', `Color preview swatch of ${hex}`);
      errorMessage.hidden = true;
    } else {
      hexOutput.textContent = 'Invalid value';
      hexOutput.classList.add('invalid');
      colorSwatch.classList.add('invalid');
      colorSwatch.setAttribute('aria-label', 'Color preview unavailable due to invalid input');
      errorMessage.textContent = 'Invalid value';
      errorMessage.hidden = false;
    }
  }

  inputs.forEach(input => {
    input.addEventListener('input', updateConverter);
    input.addEventListener('change', updateConverter);
  });

  // Initial render
  updateConverter();
});
